def title_pattern(query):
    # Explicit LIKE escape character; backslash is consequently literal too.
    return '%'+query.replace('!','!!').replace('%','!%').replace('_','!_')+'%'


class FeedRepository:
    def __init__(self,db):
        self.db=db

    def page(self,query,after,limit):
        statement=select(Video.id,Video.title,Video.duration_ms,Video.published_at,Channel.id.label('channel_id'),Channel.title.label('channel_title'),User.username).select_from(Video).join(Channel,Channel.id==Video.channel_id).join(User,User.id==Channel.user_id).where(Video.visibility=='public',Video.status=='ready',Video.moderation_state=='visible',Video.published_at.is_not(None))
        if query:
            statement=statement.where(Video.title.ilike(title_pattern(query),escape='!'))
        if after:
            statement=statement.where(tuple_(Video.published_at,Video.id)<after)
